import json,subprocess,math,hashlib
from pathlib import Path
path=Path('/workspace/analysis.json');a=json.loads(path.read_text());r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True));c=r['context'];h={t['id']:t for t in c['history']};ix={t['id']:t for t in c['trajectory_index']};ids=set(ix)
assert a['phase']=='analyze';assert a['protocol_hash']==c['protocol']['identity'];assert a['dataset_manifest_hash']==c['protocol']['data_identity']
assert a['decision']['incumbent']==c['incumbent'];assert set(a['evidence_refs'])==ids
checked_refs=0
def walk(x):
 global checked_refs
 if isinstance(x,dict):
  for k,v in x.items():
   if k in ['evidence_refs','suite_model_refs','nearest_local_work']:
    assert isinstance(v,list) and set(v)<=ids,(k,v);checked_refs+=len(v)
   if k=='trial_id':assert v in ids
   walk(v)
 elif isinstance(x,list):
  for y in x:walk(y)
 elif isinstance(x,float):assert math.isfinite(x)
walk(a)
for row in a['performance_and_cost_table']:
 k=row['id'];assert row['auc']==ix[k]['auc'];assert row['wall_seconds']==ix[k]['wall_seconds'];assert row['status']==ix[k]['status']
 if k in h:
  for key in ['source_sha256','config','parameters','embedding_parameters','dense_parameters','train_seconds','peak_gpu_bytes','error']:assert row[key]==h[k].get(key),(k,key)
  for key,v in row['validation'].items():assert v==h[k]['validation'][key]
for t in a['contrasts']:
 for m in ['auc','logloss']:assert t['candidate_minus_reference'][m]==h[t['candidate']]['validation'][m]-h[t['reference']]['validation'][m]
for t in a['factorial_interactions']:
 for m in ['auc','logloss']:assert math.isclose(t[m],sum(s*h[k]['validation'][m] for k,s in t['terms']),rel_tol=1e-12,abs_tol=1e-15)
for row in a['slice_table']:
 for k,s in row['models'].items():
  original=h[k]['validation']['slices'][row['slice']]
  for key in ['samples','positives','negatives']:assert original[key]==row[key]
  for m in ['auc','logloss']:assert s[m]==original[m]
 assert row['samples']==row['positives']+row['negatives'] and row['positives']>0 and row['negatives']>0
 for m in ['auc','logloss']:assert row['constant_tangent_minus_full'][m]==row['models']['r0008-constant_tangent'][m]-row['models']['r0008-full_bridge'][m]
for prefix in ['history_','hour_','user_train_frequency_']:
 chosen=[s for s in a['slice_table'] if s['slice'].startswith(prefix) or prefix=='history_' and s['slice']=='empty_history']
 for key in ['samples','positives','negatives']:assert sum(s[key] for s in chosen)==a['comparison_contract']['population'][key],(prefix,key)
for k in ['r0008-constant_tangent','r0008-constant_identity']:assert a['candidate_diagnostics']['latest_receipts'][k]==h[k]['candidate_diagnostics']
n=a['next_action']['cost'];assert n['residual_after_caps_and_reserve_seconds']==c['remaining_seconds']-30*c['protocol']['trial_cap_seconds']>0
for key in ['observations','interpretations','alternatives','falsifiers','evidence_refs','next_action','limitations']:assert a[key]
assert len(a['performance_and_cost_table'])==28 and len(a['slice_table'])==23
# Explicitly scope the Logloss maximum to metrics supplied in full receipts.
a['decision']['best_observed_logloss_scope']='Among the 15 current detailed receipts; older summary-only entries do not export Logloss.'
a['reproduction']['verification_result']={'status':'passed','checks':['required fields and finite JSON values','all nested trial references exist','all 28 summary identities and 15 detailed metric/config/source entries match runtime','all 15 simple contrasts and 12 signed effects recomputed','all 23 slice metrics/counts match five detailed models; disjoint history/hour/frequency bins sum to full population','latest diagnostics exactly retained','resource planning arithmetic and positive reserve residual'],'trial_reference_occurrences_checked':checked_refs,'formal_schema_validation':'Unavailable: no analysis schema/validator exported.'}
path.write_text(json.dumps(a,indent=2,allow_nan=False)+'\\n')
print(json.dumps({'status':'passed','artifact':str(path),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'bytes':path.stat().st_size,'trial_reference_occurrences_checked':checked_refs,'runtime_incumbent':a['decision']['incumbent'],'auc':a['decision']['validation_auc'],'delta_vs_previous':a['contrasts'][0]['candidate_minus_reference']}))
PY"

